#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Host: cursor

HOST_ID="cursor"
HOST_NAME="Cursor"
HOST_VERSION="unknown"
SKILLS_REL=".cursor/skills"
INVOKE="/ask-devcraft"
HOST_LOADED_CHECK="type / in the Agent chat and check that ask-devcraft and zebra-migration-probe are offered."
HOST_LAUNCH_HINT="Cursor: one Task call (a subagent block) appears in the chat."
HOST_CONTINUE_HINT="Cursor: a second Task call resumes the earlier subagent by its agent ID. The chat shows it under a new title, which is still the same worker. A fresh subagent with the whole handoff again is a FAIL; note whether you were shown any 'State' text (you must not be)."
HOST_NESTED_HINT="Cursor lets a direct subagent launch one more level, so open the subagent's block and check it holds no nested Task call."

host_prerequisites() {
  say "This needs the Cursor app (2.5 or later), signed in."
  note "Free plan: Agent works with Cursor's own models and limited usage. Cursor's docs do not"
  note "gate skills or subagents by plan, but this probe uses about five Agent turns plus"
  note "subagent runs and can exhaust a Free allowance. If it does, record the rest as skipped."
  if ! confirm "Is Cursor installed and signed in?"; then
    warn "skipping: Cursor is not available"; exit 1
  fi
  ask HOST_VERSION "Cursor version and plan (Cursor | About; e.g. 2.9.1, Free):" || true
  note "The launcher should read references/harness/cursor.md and no other harness file."
}

host_start_session() {
  step "Open the folder in Cursor (File | Open Folder), and trust it:"
  type_this "$PROJECT"
  step "Open a new chat in Agent mode (not Ask)."
}

host_transcript_home() { printf '%s' "$HOME/.cursor"; }

host_cleanup_note() {
  note "Close the folder in Cursor."
}

# Probe helpers (stages section; the library above is the wizard template, unedited).

# transcript_report MODE: what the session transcripts of this project show.
# MODE bytes: bytes that entered the main session. MODE inline: what the newest
# subagent did. Prints one line; "NOSESSION ..." when no transcript exists.
transcript_report() {
  python3 - "$1" "$HOST_ID" "$(host_transcript_home)" "$PROJECT" <<'PY'
import glob, json, os, sys, time
mode, host, home, project = sys.argv[1:5]
project = os.path.realpath(project)
slug = os.path.basename(project).replace(".", "-")
mtime = os.path.getmtime

def entries(path):
    for line in open(path, errors="replace"):
        try: yield json.loads(line)
        except ValueError: continue

def blob(v): return v if isinstance(v, str) else json.dumps(v)

def blocks(e):
    c = (e.get("message") or {}).get("content")
    if isinstance(c, str): return [{"type": "text", "text": c}]
    return [b for b in c or [] if isinstance(b, dict)]

def role(e): return e.get("role") or e.get("type")

if host in ("codex", "air"):
    # Rollouts: the CLI keeps them under sessions/, Air archives them. Children
    # are matched to the main session by parent_thread_id, not by directory.
    where = home + "/sessions and /archived_sessions"
    metas = {}
    for pattern in ("sessions/*/*/*/rollout-*.jsonl", "archived_sessions/rollout-*.jsonl"):
        for f in glob.glob(os.path.join(home, pattern)):
            if time.time() - mtime(f) > 86400: continue
            for e in entries(f):
                if e.get("type") == "session_meta":
                    p = e.get("payload") or {}
                    if os.path.realpath(p.get("cwd") or "") == project: metas[f] = p
                    break
    roots = [f for f, p in metas.items() if not p.get("parent_thread_id")]
    main = max(roots, key=mtime) if roots else None
    kids = sorted((f for f, p in metas.items() if main
                   and p.get("parent_thread_id") == metas[main].get("id")
                   and "thread_spawn" in ((p.get("source") or {}).get("subagent") or {}
                                          if isinstance(p.get("source"), dict) else {})), key=mtime)
    def payloads(f): return [e.get("payload") or {} for e in entries(f)]
    def taken_in(f):
        total = 0
        for p in payloads(f):
            if p.get("type") in ("function_call_output", "custom_tool_call_output"):
                total += len(blob(p.get("output")).encode())
            elif p.get("type") == "message" and p.get("role") == "user":
                for c in p.get("content") or []:
                    t = c.get("text") or ""
                    if t.lstrip().startswith("<skill>"): total += len(t.encode())
        return total
    def calls(f):
        return [(p.get("name") or "", blob(p.get("arguments") or p.get("input") or ""))
                for p in payloads(f) if p.get("type") in ("function_call", "custom_tool_call")]
    def last_text(f):
        out = ""
        for p in payloads(f):
            if p.get("type") == "message" and p.get("role") == "assistant":
                out = "".join(c.get("text") or "" for c in p.get("content") or []) or out
        return out
    counted = "skill body and tool results; agent messages are stored encrypted and not counted"
else:
    if host == "cursor":
        where = home + "/projects/*" + slug + "/agent-transcripts"
        files = glob.glob(os.path.join(home, "projects", "*" + slug, "agent-transcripts", "*", "*.jsonl"))
    else:
        where = home + "/projects/*" + slug
        files = glob.glob(os.path.join(home, "projects", "*" + slug, "*.jsonl"))
    main = max(files, key=mtime) if files else None
    kid_dir = (os.path.dirname(main) if host == "cursor" else main[:-6]) if main else ""
    kids = sorted(glob.glob(os.path.join(kid_dir, "subagents", "*.jsonl")), key=mtime) if main else []
    def taken_in(f):
        total = 0
        for e in entries(f):
            if role(e) != "user": continue
            for b in blocks(e):
                if b.get("type") == "text": total += len((b.get("text") or "").encode())
                elif b.get("type") == "tool_result": total += len(blob(b.get("content")).encode())
        return total
    def calls(f):
        return [(b.get("name") or "", blob(b.get("input") or "")) for e in entries(f)
                if role(e) == "assistant" for b in blocks(e) if b.get("type") == "tool_use"]
    def last_text(f):
        out = ""
        for e in entries(f):
            if role(e) == "assistant":
                out = "".join(b.get("text") or "" for b in blocks(e) if b.get("type") == "text") or out
        return out
    counted = "your messages, the skill body, tool results"

if not main:
    print("NOSESSION no session transcript for this project under " + where); sys.exit(0)

def spawned(f):
    return sum(1 for name, args in calls(f) if name in ("Agent", "Task", "spawn_agent")
               or (name == "CallDynamicTool" and '"Task"' in args))

if mode == "bytes":
    if host == "cursor":
        # Cursor stores tool calls without their results, so this is an estimate.
        reports = sum(len(last_text(k).encode()) for k in kids)
        print("ESTIMATE, not a measurement: main session took in about %d bytes (%d of your messages with "
              "the attached skill, %d of subagent reports); the results of its own %d tool calls are not "
              "stored and not counted; %d subagent transcript(s)"
              % (taken_in(main) + reports, taken_in(main), reports, len(calls(main)) - spawned(main), len(kids)))
    else:
        print("main session took in %d bytes (%s); %d subagent transcript(s) took in %d bytes"
              % (taken_in(main), counted, len(kids), sum(taken_in(k) for k in kids)))
elif not kids:
    print("NOSESSION the main session's transcript shows no subagent")
else:
    kid = kids[-1]
    read_worker = any("worker.md" in args for _, args in calls(kid))
    print("newest subagent: read worker.md: %s; tool calls: %d; subagents of its own: %d; last message: %s"
          % ("yes" if read_worker else "NO", len(calls(kid)), spawned(kid),
             " ".join(last_text(kid).split())[:200] or "(none)"))
PY
}

# flag_no_session WHY: mark the result file as having no session behind it.
flag_no_session() {
  warn "$1"
  warn "Nothing recorded here can be checked against a session. If you are re-recording an"
  warn "earlier run from memory, stop: this result file is flagged and is not evidence."
  printf '\n**FLAGGED: %s. No row in this file has a session behind it; do not keep it as evidence.**\n' "$1" >> "$RESULTS"
}

# measure_bytes: stage 4. The verdict is asked for only when a session was found.
measure_bytes() {
  local out check="Main session took in under about 15 KB for one delegated question"
  out="$(transcript_report bytes)" || out="NOSESSION the transcript could not be read"
  if [[ "$out" == NOSESSION* ]]; then
    flag_no_session "${out#NOSESSION }"
    printf '\n| Check | Result | Notes |\n| --- | --- | --- |\n| %s | UNVERIFIED | no session transcript |\n' "$check" >> "$RESULTS"
    if ! confirm "Continue recording anyway?"; then note "Stopped. Flagged results: $RESULTS"; exit 1; fi
    return 0
  fi
  say "$out"
  printf '\nBytes (stage 4): %s\n\n| Check | Result | Notes |\n| --- | --- | --- |\n' "$out" >> "$RESULTS"
  result "$check"
}

# inline_evidence: stage 6. Show and record what the newest subagent's transcript holds.
inline_evidence() {
  local out
  out="$(transcript_report inline)" || out="NOSESSION the transcript could not be read"
  if [[ "$out" == NOSESSION* ]]; then flag_no_session "${out#NOSESSION }"; return 0; fi
  say "From the transcript: $out"
  printf '\nInline fallback (stage 6), from the transcript: %s\n\n| Check | Result | Notes |\n| --- | --- | --- |\n' "${out//|//}" >> "$RESULTS"
}

Q_INVENTORY="which skill should I use to migrate a Zebra-QL schema?"
Q_CONSENT="I need to add Stripe checkout to my app. Which skill should I use?"
A_CONSENT="Yes, name it and say where to get it."

# result CHECK: ask for pass/fail/skip and one line of notes; append a table row.
result() {
  local check="$1" verdict="" notes=""
  while [[ ! "$verdict" =~ ^[pfs]$ ]]; do
    printf '  %s%s%s [p]ass / [f]ail / [s]kip: ' "$BOLD" "$check" "$RESET"
    read -r verdict || verdict="s"
  done
  case "$verdict" in p) verdict="pass" ;; f) verdict="FAIL" ;; *) verdict="skipped" ;; esac
  printf '  %sNotes (one line; what you saw, Enter for none):%s ' "$DIM" "$RESET"
  read -r notes || true
  notes="${notes//|/\/}"
  printf '| %s | %s | %s |\n' "$check" "$verdict" "$notes" >> "$RESULTS"
  printf '  %s✓ recorded%s %s: %s\n' "$GREEN" "$RESET" "$check" "$verdict"
}

# type_this TEXT: show text the human types into the agent session, and copy it
# to the clipboard when a clipboard tool exists.
type_this() {
  printf '\n    %s%s%s\n\n' "$BOLD" "$1" "$RESET"
  if command -v pbcopy >/dev/null 2>&1; then printf '%s' "$1" | pbcopy; note "(copied to the clipboard)"
  elif command -v wl-copy >/dev/null 2>&1; then printf '%s' "$1" | wl-copy; note "(copied to the clipboard)"
  fi
}

# setup_project: disposable project with the skill and two fixture skills
# copied into the host's project skill directory.
setup_project() {
  local here src dest tmp
  here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
  src="${ASK_DEVCRAFT_SRC:-$here/../../../plugins/agentic-devcraft/skills/ask-devcraft}"
  if [[ ! -f "$src/SKILL.md" ]]; then
    warn "ask-devcraft not found at $src; set ASK_DEVCRAFT_SRC to the ask-devcraft directory and re-run"
    exit 1
  fi
  src="$(cd "$src" && pwd)"
  tmp="${TMPDIR:-/tmp}"
  PROJECT="$(mktemp -d "${tmp%/}/ask-devcraft-probe-$HOST_ID.XXXXXX")"
  dest="$PROJECT/$SKILLS_REL"
  mkdir -p "$dest/zebra-migration-probe/agents" "$dest/probe-visible"
  cp -R "$src" "$dest/ask-devcraft"
  cat > "$dest/zebra-migration-probe/SKILL.md" <<'FIXTURE'
---
name: zebra-migration-probe
description: Probe fixture. Use when migrating a Zebra-QL schema. Explicit-only; it does nothing.
disable-model-invocation: true
metadata:
  opencode/autoinvoke: false
---

Probe fixture. Reply with the words "zebra fixture loaded" and do nothing else.
FIXTURE
  cat > "$dest/zebra-migration-probe/agents/openai.yaml" <<'FIXTURE'
policy:
  allow_implicit_invocation: false
FIXTURE
  cat > "$dest/probe-visible/SKILL.md" <<'FIXTURE'
---
name: probe-visible
description: Probe fixture for skill-list visibility. It does nothing.
---

Probe fixture. Reply with the word "visible" and do nothing else.
FIXTURE
  printf '# ask-devcraft probe project\n\nDisposable. Safe to delete.\n' > "$PROJECT/README.md"
  git -C "$PROJECT" init -q 2>/dev/null || true
  SKILL_PATH="$dest/ask-devcraft/SKILL.md"

  mkdir -p "$RESULTS_DIR"
  RESULTS="$RESULTS_DIR/$HOST_ID-$(date +%Y%m%d-%H%M%S).md"
  {
    printf '# ask-devcraft native probe: %s\n\n' "$HOST_NAME"
    printf -- '- Date: %s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
    printf -- '- Host version: %s\n' "$HOST_VERSION"
    printf -- '- Skill: %s\n' "$src"
    printf -- '- Skill revision: %s (%s)\n' "$(git -C "$src" rev-parse --short HEAD 2>/dev/null || echo unknown)" \
      "$(git -C "$src" status --porcelain -- . 2>/dev/null | grep -q . && echo 'uncommitted changes' || echo clean)"
    printf -- '- Project: %s (disposable)\n\n' "$PROJECT"
    printf '| Check | Result | Notes |\n| --- | --- | --- |\n'
  } > "$RESULTS"
}

run_wizard() {

TOTAL_STAGES=7
RESULTS_DIR="${RESULTS_DIR:-$HOME/.cache/ask-devcraft-probes/results}"
ENV_FILE="/dev/null"   # this wizard stores nothing in a .env file
PROJECT=""; RESULTS=""; SKILL_PATH=""

banner "ask-devcraft native probe: $HOST_NAME"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Set up a disposable project"
host_prerequisites
setup_project
say "Created a throwaway project with the skill copied in project-locally:"
note "$PROJECT/$SKILLS_REL/ask-devcraft"
say "It also holds two fixture skills: probe-visible (ordinary) and"
say "zebra-migration-probe (explicit-only, hidden from the model's skill list)."
say "Nothing is installed into your $HOST_NAME home, and nothing is published."
note "Results will be written to: $RESULTS"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Start a fresh $HOST_NAME session in that project"
host_start_session
say "Leave it open. Every later stage tells you exactly what to type there."
step "First confirm the host loaded the skill: $HOST_LOADED_CHECK"
result "Skill loads from the project directory"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Subagent launch and full inventory"
say "In the $HOST_NAME session, type exactly:"
type_this "$INVOKE $Q_INVENTORY"
say "Answer permission prompts for READS only. Wait for the final answer."
step "Launch passes when the session starts exactly one subagent with fresh context"
note "$HOST_LAUNCH_HINT"
step "and does not itself read worker.md, references/index.md or any catalog."
result "Subagent launch from the main session"
step "Inventory passes when the answer names zebra-migration-probe as installed here"
step "and as something only you can invoke. That skill is hidden from the model's"
step "own list, so the worker can only have found it through the host inventory."
result "Full inventory visible to the worker"
step "Did any read of a skill directory outside the project ask you for permission?"
result "No permission prompt for inventory reads (fail = it prompted; say where)"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Bytes that entered the main session"
say "This measures the session you just used, after exactly one question."
note "Reference from OpenCode: about 9 to 11 KB delegated, 96 to 138 KB inline."
measure_bytes

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Consent question that names no skill, then the same worker continues"
say "In the SAME session, type exactly:"
type_this "$INVOKE $Q_CONSENT"
step "Expected: a question asking whether it may introduce a collection you have"
step "nothing from. It must describe only the kind of skill. FAIL if it names any skill,"
step "plugin, marketplace or collection (\"an official Stripe plugin\" is a name)."
note "If you already have a Stripe or Vercel skill installed it will answer directly:"
note "record that as skipped and say which skill it found."
result "Consent question names no skill"
say "Now reply in the same session, exactly:"
type_this "$A_CONSENT"
step "Continuation passes when your reply goes to the SAME worker, no new one starts,"
step "and a recommendation naming the skill and where to get it comes back."
note "$HOST_CONTINUE_HINT"
result "Reply continued the same worker"
step "Relay passes when the session's message IS the worker's question, then its answer,"
step "word for word: no bullets, no trimming, no claim or question of its own, and your"
step "reply reached the worker exactly as you typed it."
result "Answers relayed unchanged"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Inline fallback when invoked inside a subagent"
say "In the same session, type exactly (one message):"
type_this "Start exactly one subagent with fresh context and give it exactly this prompt: \"The user asked: $Q_INVENTORY To answer, read the file $SKILL_PATH and follow it. Read-only: install nothing.\" Wait for it, show me its report verbatim, and tell me whether it started any subagent of its own."
step "Passes only when that subagent read worker.md, answered the question itself (it"
step "should say the routing ran in its own session) and started NO subagent of its own."
step "FAIL when it refused (\"the skill must be invoked by the user\"), stopped before"
step "answering, or never read worker.md. Starting no subagent is not enough to pass."
note "$HOST_NESTED_HINT"
inline_evidence
result "Inline fallback inside a subagent, no second delegation"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Wrap up"
say "Anything else worth keeping (host quirks, wording the launcher got wrong)?"
printf '  %sFree-form note, one line (Enter for none):%s ' "$DIM" "$RESET"
extra=""
read -r extra || true
[[ -n "$extra" ]] && printf '\n%s\n' "$extra" >> "$RESULTS"
say "Close the $HOST_NAME session now."
if confirm "Delete the disposable project $PROJECT?"; then
  rm -rf "$PROJECT"
  say "Deleted."
else
  note "Kept: $PROJECT"
fi
host_cleanup_note

finish
printf '  Results: %s\n\n' "$RESULTS"
cat "$RESULTS"
}

run_wizard "$@"; exit
